"use client"

import animation from "react-useanimations/lib/hardDrive"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Hard Drive" from https://useanimations.com (MIT): https://useanimations.com/icons/hard-drive
export function AnimatedHardDrive(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover-replay"
      {...props}
    />
  )
}
